import heapq

def distanta_minima(graf, start, destinatie):
    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, v = heapq.heappop(heap)
        if v == destinatie:
            return d
        if d > dist[v]:
            continue
        for u, w in graf[v]:
            if u not in dist or d + w < dist[u]:
                dist[u] = d + w
                heapq.heappush(heap, (dist[u], u))
    return -1

